    @BeforeAll static void schema()throws Exception{String requestedEvidence=System.getProperty("dossier.evidence");if(requestedEvidence==null)System.setProperty("dossier.evidence","docs/product/o001/evidence/task-87");try{DossierMaterialsMysqlTest.schema();}finally{if(requestedEvidence==null)System.clearProperty("dossier.evidence");}evidence=DossierMaterialsMysqlTest.evidence;var db=new JdbcTemplate(new DriverManagerDataSource(DossierMaterialsMysqlTest.url,DossierMaterialsMysqlTest.user,DossierMaterialsMysqlTest.password));String sql=Files.readString(DossierMaterialsMysqlTest.workspace.resolve("ruoyi-ai/docs/script/sql/update/2026-10-22-dossier-claims.sql")).replaceAll("(?m)--.*$","");for(String statement:sql.split(";"))if(!statement.isBlank())db.execute(statement);}
