    @AfterEach void close(){fixture.close();}
    static byte[] pdf(String...pages)throws Exception{try(var doc=new PDDocument();var out=new ByteArrayOutputStream()){for(String text:pages){var page=new PDPage();doc.addPage(page);try(var stream=new PDPageContentStream(doc,page)){stream.beginText();stream.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),11);stream.newLineAtOffset(35,750);for(String line:text.split("\n")){stream.showText(line);stream.newLineAtOffset(0,-18);}stream.endText();}}doc.save(out);return out.toByteArray();}}
    CaseFileVersion upload(String name,String...pages)throws Exception{var v=fixture.upload(name,pdf(pages),null,false);fixture.execute(v);return v;}
    CaseSourceAnchor anchor(CaseFileVersion v,int page,String fragment,int occurrence){String text=fixture.materials.pages(11L,v.getId()).get(page-1).getTextContent();int start=-1;for(int i=0;i<=occurrence;i++)start=text.indexOf(fragment,start+1);assertTrue(start>=0);return anchors.create(11L,new DossierAnchorService.Create(v.getId(),page,"text_offset",start,start+fragment.length(),fragment,null,null,null,false));}
    DossierClaimService.Edit edit(int version,String text,List<DossierClaimSchema.Link> links,String state){return new DossierClaimService.Edit(version,"excerpt",text,new LinkedHashMap<>(),links,state,"合成样本对照原文逐项人工核对");}
    static DossierClaimSchema.Link supports(CaseSourceAnchor a){return new DossierClaimSchema.Link(a.getId().toString(),"supports");}
    CaseClaim manual(CaseSourceAnchor...sources){return claims.manual(11L,edit(1,"Synthetic manual claim",Arrays.stream(sources).map(DossierClaimsMysqlTest::supports).toList(),"pending_review"));}
    void allow(){when(boundaries.find(any())).thenAnswer(call->Optional.of(new DossierOutboundPolicy.Grant(call.getArgument(0),Instant.now().plusSeconds(300))));}
    DossierClaimExtractor.Receipt enqueue(CaseFileVersion...versions){return extraction.request(11L,new DossierClaimExtractor.Request(Arrays.stream(versions).map(CaseFileVersion::getId).toList(),7L,UUID.randomUUID().toString()));}
    void execute(DossierClaimExtractor.Receipt receipt){long job=Long.parseLong(receipt.jobId());String lease=UUID.randomUUID().toString();assertTrue(fixture.worker.claim(job,lease));fixture.worker.run(job,lease);}
    String validResponse(String data){try{var offered=JSON.readTree(data);var first=offered.get(0);return BankStatementService.json(Map.of("claims",List.of(Map.of("kind","excerpt","text","Synthetic model candidate","originalText",first.get("text").asText(),"risk","normal","values",new LinkedHashMap<String,Object>(){{put("dateRaw",null);put("amountRaw",null);put("name",null);put("currency",null);}},"sources",List.of(Map.of("anchorId",first.get("anchorId").asText(),"relation","supports"))))));}catch(Exception e){throw new IllegalStateException(e);}}
    @Test void offsetsDisambiguateRepeatedMoneyAndWrongPageOrFragmentIsRejected()throws Exception{
        var v=upload("two-pages.pdf","PartyA paid 50000.00. PartyB paid 50000.00.","Witness on second page.");var first=anchor(v,1,"50000.00",0);var second=anchor(v,1,"50000.00",1);assertNotEquals(first.getId(),second.getId());assertNotEquals(first.getFragmentStart(),second.getFragmentStart());assertTrue(anchors.resolve(11L,first.getId()).verified());assertTrue(anchors.resolve(11L,second.getId()).verified());
        assertThrows(ServiceException.class,()->anchors.create(11L,new DossierAnchorService.Create(v.getId(),null,"text_offset",first.getFragmentStart(),first.getFragmentEnd(),"50000.00",null,null,null,false)));
        assertThrows(ServiceException.class,()->anchors.create(11L,new DossierAnchorService.Create(v.getId(),2,"text_offset",first.getFragmentStart(),first.getFragmentEnd(),"50000.00",null,null,null,false)));
        assertThrows(ServiceException.class,()->anchors.create(11L,new DossierAnchorService.Create(v.getId(),1,"text_offset",0,3,null,null,null,null,false)));
    }
    @Test void multiFileSourcesReviewAndCrossCaseTenantRequestsAreIsolated()throws Exception{
        var a=anchor(upload("a.pdf","PartyA signed."),1,"PartyA",0);var b=anchor(upload("b.pdf","Witness saw PartyA.","Contradictory PartyB statement."),2,"PartyB",0);var c=manual(a,b);var detail=claims.detail(11L,c.getId());assertEquals(2,detail.sources().size());assertNotEquals(detail.sources().get(0).anchor().getFileVersionId(),detail.sources().get(1).anchor().getFileVersionId());var links=List.of(supports(a),new DossierClaimSchema.Link(b.getId().toString(),"contradicts"));c=claims.edit(11L,c.getId(),edit(c.getVersion(),"Conflicting statements remain unresolved",links,"confirmed"));assertEquals("confirmed",c.getReviewStatus());assertEquals(2,claims.detail(11L,c.getId()).links().size());final Long id=c.getId();fixture.actor=202;assertThrows(ServiceException.class,()->claims.detail(11L,id));assertThrows(ServiceException.class,()->anchors.resolve(22L,a.getId()));fixture.actor=101;fixture.tenant="111111";assertThrows(ServiceException.class,()->anchors.resolve(33L,a.getId()));assertThrows(ServiceException.class,()->claims.detail(33L,id));
    }
