        var v=upload("partial.pdf","Readable first page.","Unread second page.");fixture.jdbc.update("UPDATE lawyer_case_file_page SET extract_status='failed',text_content='',text_hash=? WHERE file_version_id=? AND page_index=2",DossierAnchorService.hash(""),v.getId());allow();var run=enqueue(v);execute(run);assertEquals("partial",extraction.runs(11L).get(0).get("state"));assertEquals(1,run.readablePages());assertEquals(2,run.totalPages());response=data->validResponse(data).replace("\"risk\":\"normal\"","\"risk\":\"normal\",\"reviewStatus\":\"confirmed\"");var bad=enqueue(v);execute(bad);assertEquals("failed",extraction.runs(11L).get(0).get("state"));assertTrue(extraction.chunks(11L,Long.valueOf(bad.runId())).get(0).get("rejections").toString().contains("INVALID_JSON_SCHEMA"));assertTrue(claims.list(11L,null).rows().stream().noneMatch(c->"confirmed".equals(c.getReviewStatus())));
