    @Test void splitMergeAndConcurrentVersionsPreserveSourcesAndAudit()throws Exception{
        var a=anchor(upload("atomic.pdf","PartyA signed and PartyB witnessed."),1,"PartyA signed and PartyB witnessed.",0);var c=manual(a);var edit=edit(c.getVersion(),"First revision",List.of(supports(a)),"pending_review");var newer=claims.edit(11L,c.getId(),edit);assertEquals(409,assertThrows(ServiceException.class,()->claims.edit(11L,c.getId(),edit)).getCode());var parts=claims.split(11L,newer.getId(),new DossierClaimService.Split(newer.getVersion(),List.of(edit(1,"PartyA signed",List.of(supports(a)),"pending_review"),edit(1,"PartyB witnessed",List.of(supports(a)),"pending_review")),"逐句拆分保留原文和来源"));assertEquals(2,parts.size());assertEquals("excluded",claims.detail(11L,c.getId()).claim().getReviewStatus());var merged=claims.merge(11L,new DossierClaimService.Combine(parts.stream().map(CaseClaim::getId).toList(),parts.stream().map(CaseClaim::getVersion).toList(),"Combined reviewed proposition","人工合并但不自动确认子项"));assertEquals("pending_review",merged.getReviewStatus());assertEquals(1,claims.detail(11L,merged.getId()).sources().size());assertTrue(claims.detail(11L,merged.getId()).history().size()>0);
    }
