    @Test void guardedClaimsMigrationChecksChecksumIdempotencyAndSyntheticBackupRestore()throws Exception{
        Path root=DossierMaterialsMysqlTest.workspace,classes=Files.createTempDirectory("claims-migration-classes-");String javaExe=Path.of(System.getProperty("java.home"),"bin","java.exe").toString(),javac=Path.of(System.getProperty("java.home"),"bin","javac.exe").toString();var compiler=new ProcessBuilder(javac,"-encoding","UTF-8","-d",classes.toString(),root.resolve("ruoyi-ai/scripts/deploy/DossierMigration.java").toString(),root.resolve("ruoyi-ai/scripts/deploy/DossierExtensionMigration.java").toString()).redirectErrorStream(true).redirectOutput(evidence.resolve("migration-compile.log").toFile()).start();assertTrue(compiler.waitFor(45,java.util.concurrent.TimeUnit.SECONDS));assertEquals(0,compiler.exitValue());
        String db=DossierMaterialsMysqlTest.database;assertTrue(db.startsWith("codex_dossier85_"));var dump=new StringBuilder("-- SYNTHETIC ONLY\n");try(var c=java.sql.DriverManager.getConnection(DossierMaterialsMysqlTest.url,DossierMaterialsMysqlTest.user,DossierMaterialsMysqlTest.password);var statement=c.createStatement()){
            var tables=new ArrayList<String>();try(var r=statement.executeQuery("SHOW TABLES")){while(r.next())tables.add(r.getString(1));}for(String table:tables){try(var r=statement.executeQuery("SHOW CREATE TABLE `"+table+"`")){r.next();dump.append(r.getString(2)).append(";\n");}try(var r=statement.executeQuery("SELECT * FROM `"+table+"`")){while(r.next()){dump.append("INSERT INTO `").append(table).append("` VALUES(");for(int i=1;i<=r.getMetaData().getColumnCount();i++){if(i>1)dump.append(',');Object value=r.getObject(i);dump.append(value==null?"NULL":"'"+value.toString().replace("\\","\\\\").replace("'","''")+"'");}dump.append(");\n");}}}
            String restore=db+"_claims_restore";statement.execute("CREATE DATABASE `"+restore+"` CHARACTER SET utf8mb4");c.setCatalog(restore);try(var restored=c.createStatement()){for(String sql:dump.toString().replaceAll("(?m)--.*$","").split(";\\n"))if(!sql.isBlank())restored.execute(sql);try(var count=restored.executeQuery("SELECT COUNT(*) FROM lawyer_case")){count.next();assertEquals(3,count.getInt(1));}}
        }
        Path backup=evidence.resolve("claims-synthetic-backup.sql"),receipt=evidence.resolve("claims-synthetic-backup.properties");Files.writeString(backup,dump.toString());var props=new Properties();props.setProperty("database",db);props.setProperty("file",backup.toString());props.setProperty("sha256",DossierFiles.hash(Files.readAllBytes(backup)));try(var out=Files.newBufferedWriter(receipt)){props.store(out,"SYNTHETIC ONLY; restored to separate synthetic DB");}
        String driver=Path.of(Class.forName("com.mysql.cj.jdbc.Driver").getProtectionDomain().getCodeSource().getLocation().toURI()).toString();var command=new ArrayList<>(List.of(javaExe,"-cp",classes+File.pathSeparator+driver,"DossierExtensionMigration","migrate",root.toString(),"2026-10-22-dossier-claims.sql"));var env=new HashMap<String,String>();env.put("DOSSIER_JDBC_URL",DossierMaterialsMysqlTest.url);env.put("DOSSIER_DB_USER",DossierMaterialsMysqlTest.user);env.put("DOSSIER_DB_PASSWORD",DossierMaterialsMysqlTest.password);env.put("DOSSIER_EXPECTED_DATABASE",db);env.put("DOSSIER_OPERATOR","claims-synthetic-rehearsal");env.put("DOSSIER_BACKUP_RECEIPT",receipt.toString());assertNotEquals(0,invoke(command,env,"migration-unregistered.log"));command.add("--resume");assertEquals(0,invoke(command,env,"migration-resume.log"));command.remove(command.size()-1);assertEquals(0,invoke(command,env,"migration-repeat.log"));String checksum=DossierFiles.hash(Files.readAllBytes(root.resolve("ruoyi-ai/docs/script/sql/update/2026-10-22-dossier-claims.sql")));fixture.jdbc.update("UPDATE stage4_schema_migration SET sha256=REPEAT('0',64) WHERE version='2026-10-22-dossier-claims.sql'");try{assertNotEquals(0,invoke(command,env,"migration-checksum.log"));}finally{fixture.jdbc.update("UPDATE stage4_schema_migration SET sha256=? WHERE version='2026-10-22-dossier-claims.sql'",checksum);}assertEquals(3,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM lawyer_case",Integer.class));assertEquals(1,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM stage4_schema_migration WHERE version='2026-10-22-dossier-claims.sql'",Integer.class));Files.writeString(evidence.resolve("claims-migration-rehearsal.json"),BankStatementService.json(Map.of("syntheticOnly",true,"database",db,"checks",List.of("full_schema_and_rows_restored_to_new_synthetic_database","unregistered_refused","explicit_resume_pass","repeat_noop","checksum_refused","legacy_case_count_and_one_ledger_preserved"))));
    }
