    @Test void retryKeepsUnknownPriorUsageAndSuccessfulChunksAreNeverRepeated()throws Exception{
        var v=upload("retry.pdf","Retry synthetic source.");allow();doThrow(new ServiceException("synthetic provider timeout",503)).when(model).generate(anyString(),anyLong(),any(),anyString());var run=enqueue(v);execute(run);long held=((Number)extraction.budget(11L).get("tokensCharged")).longValue();assertTrue(held>0);assertEquals("failed_usage_unknown",fixture.jdbc.queryForObject("SELECT state FROM lawyer_case_ai_attempt",String.class));doAnswer(call->new DossierClaimModel.Output(validResponse(call.getArgument(3)),100L,50L)).when(model).generate(anyString(),anyLong(),any(),anyString());extraction.retry(11L,Long.valueOf(run.runId()));execute(run);assertEquals(2,fixture.jdbc.queryForObject("SELECT COUNT(*) FROM lawyer_case_ai_attempt",Integer.class));assertEquals(held+150,((Number)extraction.budget(11L).get("tokensCharged")).longValue());assertNull(extraction.runs(11L).get(0).get("actualTokens"));assertEquals(409,assertThrows(ServiceException.class,()->extraction.retry(11L,Long.valueOf(run.runId()))).getCode());
    }
    static int invoke(List<String> command,Map<String,String> env,String log)throws Exception{var builder=new ProcessBuilder(command).redirectErrorStream(true).redirectOutput(evidence.resolve(log).toFile());builder.environment().putAll(env);var process=builder.start();assertTrue(process.waitFor(30,java.util.concurrent.TimeUnit.SECONDS));return process.exitValue();}
